// Generated by crates/xtask from the Rust question model.
// Do not edit by hand; run ./build.sh (or cargo run -p xtask -- tsgen).

/**
 * Time limits applied to a question or an attempt.
 *
 * Server time is authoritative; a browser clock is display only. Keeping the
 * limit in the model and the verdict in `crates/domain` is what makes the
 * outcome invariant under client clock skew.
 */
export type TimingPolicy =
  | { kind: "untimed" }
  | {
      kind: "perQuestion";
      seconds: number;
      graceSeconds: number;
    }
  | {
      kind: "perAttempt";
      seconds: number;
      graceSeconds: number;
    };
